algorithms.pseudocode:
INPUT: valuation v, set S, universe U
OUTPUT: cl_v(S) = {x in U | v(x) <= max_{s in S} v(s)}

1. Compute sup = max(v(s) for s in S), or 0 if S is empty
2. Return {x in U : v(x) <= sup}

algorithms.code:
def valuation_closure(v, S, universe):
    sup_val = max((v[s] for s in S), default=0)
    return frozenset(x for x in universe if v[x] <= sup_val)

def is_gauge_realizable(cl_fn, universe):
    closed = compute_all_closed_sets(cl_fn, universe)
    for S in closed:
        for T in closed:
            if not (S.issubset(T) or T.issubset(S)):
                return False, None
    v = reconstruct_valuation(cl_fn, universe)
    return True, v

def reconstruct_valuation(cl_fn, universe):
    cl_empty = cl_fn(frozenset())
    base = len(cl_empty)
    return {x: len(cl_fn(frozenset([x]))) - base for x in universe}
